DARK_MODE_STYLESHEET = '\nQWidget {\n    background-color: #191919;\n    color: #E0E0E0;\n    font-family: "Inter", "Segoe UI", "Helvetica Neue", sans-serif;\n    font-size: 14px;\n}\n\nQPushButton {\n    background-color: #D3D3D3;\n    color: #000000;\n    border: none;\n    padding: 5px 10px;\n    border-radius: 4px;\n    font-weight: bold;\n    font-size: 16px;\n\n}\n\nQPushButton:focus {\n    outline: none;\n    }\n\nQPushButton:disabled {\n    background-color: #505050;\n    color: #000000;\n    border: none;\n    padding: 5px 10px;\n    border-radius: 4px;\n    font-weight: bold;\n    font-size: 16px;\n}\n\nQPushButton:hover {\n    background-color: #C0C0C0;\n}\n\nQPushButton:pressed {\n    background-color: #A9A9A9;\n}\n\nQListWidget {\n    background-color: #191919;\n    color: #FFFFFF;\n    border: 0px solid #606060;\n    padding: 4px;\n}\n\nQListView::item:selected {\n    background: #191919;\n    color: white\n    }\n\nQListView::item:hover {\n    background: #193b2a; \n    outline-color: #193b2a; \n    color: white\n    }\n\nQListView {\n    outline: 0\n    }\n\nQLineEdit, QTextEdit {\n    background-color: #2A2A2A;\n    color: #FFFFFF;\n    border: 1px solid #444;\n    padding: 4px;\n}\n\nQLabel {\n    color: #E0E0E0;\n}\n\nQScrollBar:vertical, QScrollBar:horizontal {\n    background: #303030;\n    width: 10px;\n    height: 10px;\n    margin: 0px;\n}\n\nQScrollBar::handle:vertical, QScrollBar::handle:horizontal {\n    background: #888;               /* more visible than #555 */\n    border-radius: 4px;\n    min-height: 20px;\n    min-width: 20px;\n}\n\nQScrollBar::add-line, QScrollBar::sub-line {\n    background: none;\n    height: 0px;\n    width: 0px;\n    border: none;\n}\n\nQScrollBar::add-page, QScrollBar::sub-page {\n    background: none;\n}\nQGroupBox {\n    font-weight: bold;\n    font-size: 10pt;\n    border: 1px solid #606060;\n    border-radius: 4px;\n    margin-top: 10px;\n}\nQGroupBox::title {\n    subcontrol-origin: margin;\n    subcontrol-position: top left;\n    padding: 0px 6px;\n    background-color: #191919;\n    color: #E0E0E0;\n}\nQTextBrowser {\n    border: 1px solid #303030;\n    border-radius: 4px;\n    background-color: #191919;\n}\nQTreeView {\n    background: #F0F0F0;\n    alternate-background-color: lightgray;\n    selection-background-color: #193b2a\n    color: #000000\n} \n\nQProgressBar {\n    border: 1px solid #444;\n    border-radius: 4px;\n    background-color: #2A2A2A;\n    text-align: center;\n    color: #E0E0E0;\n    font-weight: bold;\n    font-size: 14px;\n}\n\nQProgressBar::chunk {\n    background-color: #0075c9;\n    border-radius: 4px;\n}\n'

SYNC_SELECTION_TREE_STYLESHEET = '\n\nQTreeView {\n    background: #F0F0F0;\n    alternate-background-color: lightgray;\n\n    color: #000000;\n\n}\nQTreeView::indicator:checked {\n    border: 1px solid #1E1E1E;\n    border-radius: 4px;\n    background-color: #0075c9;\n}\nQTreeView::indicator:unchecked {\n    border: 1px solid #1E1E1E;\n    border-radius: 4px;\n    background-color: transparent;\n}\n\n'

